-- Données de démonstration (E0.10) : compte du conseiller, catalogue du simulateur, un dossier par étape clé.
-- Rejoué par `make seed` et par `make reset` (après les migrations). Rejouable sans doublon.
-- Vérifié par supabase/scripts/test_seed.sql (make test-db, et en CI).

-- Compte de démonstration du conseiller (E0.11), pour se connecter sur /connexion en local.
-- E-mail : conseiller@offthemap.test · mot de passe : offthemap-demo (base locale uniquement).
  instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
  raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
  confirmation_token, recovery_token, email_change, email_change_token_new
) values (
  '00000000-0000-0000-0000-000000000000', '11111111-1111-4111-8111-111111111111', 'authenticated', 'authenticated',
  'conseiller@offthemap.test', extensions.crypt('offthemap-demo', extensions.gen_salt('bf')), now(),
  '{"provider":"email","providers":["email"]}', '{}', now(), now(),
  '', '', '', ''
) on conflict (id) do nothing;

values (
  gen_random_uuid(), '11111111-1111-4111-8111-111111111111', '11111111-1111-4111-8111-111111111111', 'email',
  '{"sub":"11111111-1111-4111-8111-111111111111","email":"conseiller@offthemap.test","email_verified":true}',
  now(), now(), now()
) on conflict (provider_id, provider) do nothing;

values ('11111111-1111-4111-8111-111111111111', 'Camille (démo)')
on conflict (id) do nothing;

-- Catalogue (E0.10) : les 9 prestations du simulateur du formateur (server/catalogue.py), mêmes identifiants.
-- Prix en centimes. Un second import met à jour sans créer de doublon.
on conflict (id) do update set type = excluded.type, nom = excluded.nom, destination = excluded.destination,
  prix_unitaire_cents = excluded.prix_unitaire_cents, capacite = excluded.capacite, description = excluded.description,
  tags = excluded.tags, importe_le = excluded.importe_le, actif = true;

-- Dossiers de démonstration (E0.10) : un dossier par étape clé du parcours, à Nantes, du 7 au 8 novembre 2026.
-- Données fictives. Les options et réservations ci-dessous n'existent pas sur le simulateur : elles servent à l'affichage.
-- Rejouable : les dossiers de démonstration sont supprimés puis recréés à chaque `make seed`.
delete from dossiers where id in ('d0551e00-0000-4000-8000-000001000000', 'd0551e00-0000-4000-8000-000002000000', 'd0551e00-0000-4000-8000-000003000000', 'd0551e00-0000-4000-8000-000004000000', 'd0551e00-0000-4000-8000-000005000000', 'd0551e00-0000-4000-8000-000006000000', 'd0551e00-0000-4000-8000-000007000000', 'd0551e00-0000-4000-8000-000008000000', 'd0551e00-0000-4000-8000-000009000000', 'd0551e00-0000-4000-8000-000010000000', 'd0551e00-0000-4000-8000-000011000000', 'd0551e00-0000-4000-8000-000012000000', 'd0551e00-0000-4000-8000-000013000000');

